          "lombardo_ovid1": "Of bodies changed to other forms I tell; / You gods, who changed them too, inspire my song / And lead my poem down in unbroken course / From the world's birth to my own day.",
          "fantham_ovid1": "My mind is inclined to speak of forms changed into new bodies. You gods, inspire my undertaking (for you also transformed them), and guide my continuous song from the world's first origin down to my own times.",
          "feldherr_ovid1": "I intend to speak of bodies transformed into new shapes. Gods, inspire my beginnings, for you yourselves have changed them, and guide my continuous poem from the world's first origin to my own times."
