    "segments": [
      {
        "ref": "Catil.1.1",
        "lineNum": 1,
        "source": "Quo usque tandem abutere, Catilina, patientia nostra?",
        "literal": "To what point finally will you abuse, Catiline, patience our?",
        "translations": {
          "yonge": "When, O Catiline, do you mean to cease abusing our patience?",
          "lord": "How long, Catiline, will you abuse our patience?",
          "grant": "How long, Catiline, will you go on abusing our forbearance?",
          "guthrie": "How far, O Catiline! wilt thou abuse our patience?",
          "duncan": "How far, O Catiline, wilt thou abuse our patience?",
          "shuckburgh": "How long, pray, Catiline, will you abuse our patience?",
          "berry": "How much longer, Catiline, will you continue to abuse our patience?",
          "powell": "How much longer, Catiline, will you try our patience?",
          "macdonald": "How far, Catiline, will you abuse our patience?",
          "ref": "Catil.1.1",
          "blakiston_catil": "How far at length, Catiline, wilt thou abuse our patience? How long still will that frenzy of thine baffle us?",
          "hodge_catil": "How long, Catiline, will you abuse our patience? How long will your madness continue to mock us?",
          "gardiner_catil": "How long then, Catiline, wilt thou abuse our patience? How long shall that mad fury of thine mock us?",
          "ker_catil": "How long, Catiline, will you abuse our patience? How long will that madness of yours baffle us?",
          "habicht_catil": "How far will you go, Catiline, in abusing our patience? How much longer will that frenzy of yours make sport of us?",
          "king_catil": "How far, Catiline, wilt thou strain our patience? How long still will that madness of thine insult us?",
          "berry_catil": "How long, Catiline, will you go on abusing our patience? How much longer will your madness make a mockery of us?",
          "habinek_catil": "How much longer, Catiline, will you abuse our patience? How long still will that madness of yours elude us?",
          "vasaly_catil": "How far, Catiline, will you go on abusing our patience? How long will your madness mock us?",
          "powell_catil": "How long, Catiline, will you continue to abuse our patience? How much longer will that madness of yours mock us?",
          "manuwald_catil": "For how long, Catiline, will you continue to abuse our patience? How far will your unbridled audacity flaunt itself?"
        },
        "variants": [
          {
            "reading": "abutere",
            "source": "All primary MSS",
            "meaning": "'abuse, exhaust, take advantage of (fut. indic. -ere for -eris)'",
            "editorialNote": "Abutor takes the ablative (patientia nostra)."
          }
        ],
        "notes": "Quo usque tandem: The most celebrated rhetorical question in Roman oratory, opening ex abrupto (without standard polite preamble).",
        "vocab": [
          {
            "word": "abutere",
            "lemma": "abutor",
            "meaning": "abuse, misuse, consume entirely",
            "link": "https://logeion.uchicago.edu/abutor"
          },
          {
            "word": "patientia",
            "lemma": "patientia",
            "meaning": "patience, forbearance, endurance",
            "link": "https://logeion.uchicago.edu/patientia"
          }
        ]
      },
      {
        "ref": "Catil.1.2",
        "lineNum": 2,
        "source": "quam diu etiam furor iste tuus nos eludet?",
        "literal": "how long still madness that of yours us will mock?",
        "translations": {
          "yonge": "How long is that madness of yours still to mock us?",
          "lord": "How long will that frenzy of yours mock us?",
          "grant": "How long will that unbridled audacity of yours baffle us?",
          "guthrie": "How long shall thy frantic rage baffle our efforts?",
          "duncan": "How long shall that frantic rage of thine baffle our justice?",
          "shuckburgh": "How long will that madness of yours baffle our vigilance?",
          "berry": "How long will that madness of yours go on mocking us?",
          "powell": "How long will that madness of yours continue to mock us?",
          "macdonald": "How long will that madness of yours mock us?",
          "ref": "Catil.1.2",
          "blakiston_catil": "To what limit will thy unbridled audacity vaunt itself?",
          "hodge_catil": "To what end will your unbridled audacity display itself?",
          "gardiner_catil": "To what bounds will thy unbridled audacity boast itself?",
          "ker_catil": "To what lengths will your unbridled audacity flaunt itself?",
          "habicht_catil": "To what extreme will your unbridled audacity display itself?",
          "king_catil": "To what goal will thy unbridled audacity toss its head?",
          "berry_catil": "To what limits will your unbridled audacity flaunt itself?",
          "habinek_catil": "To what end will your unbridled audacity flaunt itself?",
          "vasaly_catil": "To what limit will your unbridled boldness flaunt itself?",
          "powell_catil": "To what end will your uncontrolled arrogance display itself?",
          "manuwald_catil": "To what extreme will your unbridled boldness display itself?"
        },
        "notes": "iste: The demonstrative of contempt ('that despicable madness of yours')."
      }
    ],
    "era": "Roman Republic",
    "period": "1st Century BCE"
